module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiButtonEmpty,\n  EuiCard,\n  EuiIcon,\n  EuiFlexGroup,\n  EuiFlexItem,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      card1Selected: true,\n      card2Selected: false,\n    };\n  }\n\n  card1Clicked = () => {\n    this.setState({\n      card1Selected: !this.state.card1Selected,\n    });\n  };\n\n  card2Clicked = () => {\n    this.setState({\n      card2Selected: !this.state.card2Selected,\n    });\n  };\n\n  render() {\n    const cardFooterContent = (\n      <EuiButtonEmpty iconType=\"iInCircle\" size=\"xs\">\n        More details\n      </EuiButtonEmpty>\n    );\n\n    return (\n      <EuiFlexGroup gutterSize=\"l\">\n        <EuiFlexItem>\n          <EuiCard\n            icon={<EuiIcon size=\"xxl\" type=\"logoSketch\" />}\n            title=\"Sketch\"\n            description=\"Example of a short card description.\"\n            footer={cardFooterContent}\n            selectable={{\n              onClick: this.card1Clicked,\n              isSelected: this.state.card1Selected,\n            }}\n          />\n        </EuiFlexItem>\n        <EuiFlexItem>\n          <EuiCard\n            icon={<EuiIcon size=\"xxl\" type=\"logoGCP\" />}\n            title=\"Google\"\n            description=\"Example of a longer card description. See how the footers stay lined up.\"\n            footer={cardFooterContent}\n            selectable={{\n              onClick: this.card2Clicked,\n              isSelected: this.state.card2Selected,\n            }}\n          />\n        </EuiFlexItem>\n        <EuiFlexItem>\n          <EuiCard\n            icon={<EuiIcon size=\"xxl\" type=\"logoAerospike\" />}\n            title=\"Not Adobe\"\n            description=\"Example of a short card description.\"\n            footer={cardFooterContent}\n            selectable={{\n              onClick: () => {},\n              isDisabled: true,\n            }}\n          />\n        </EuiFlexItem>\n      </EuiFlexGroup>\n    );\n  }\n}\n"