module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiPopover,\n  EuiFilterGroup,\n  EuiFilterButton,\n  EuiIcon,\n  EuiSpacer,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isPopoverOpen: false,\n      isFilterOn: false,\n      isOnFilterOn: false,\n      isOffFilterOn: false,\n    };\n  }\n\n  toggleFilter = () => {\n    this.setState(prevState => ({\n      isFilterOn: !prevState.isFilterOn,\n    }));\n  };\n\n  toggleOnFilter = () => {\n    this.setState(prevState => ({\n      isOnFilterOn: !prevState.isOnFilterOn,\n      isOffFilterOn:\n        prevState.isOffFilterOn && !prevState.isOnFilterOn\n          ? false\n          : prevState.isOffFilterOn,\n    }));\n  };\n\n  toggleOffFilter = () => {\n    this.setState(prevState => ({\n      isOffFilterOn: !prevState.isOffFilterOn,\n      isOnFilterOn:\n        prevState.isOnFilterOn && !prevState.isOffFilterOn\n          ? false\n          : prevState.isOnFilterOn,\n    }));\n  };\n\n  onButtonClick() {\n    this.setState({\n      isPopoverOpen: !this.state.isPopoverOpen,\n    });\n  }\n\n  closePopover() {\n    this.setState({\n      isPopoverOpen: false,\n    });\n  }\n\n  render() {\n    const button = (\n      <EuiFilterButton\n        iconType=\"arrowDown\"\n        onClick={this.onButtonClick.bind(this)}\n        isSelected={this.state.isPopoverOpen}\n        numFilters={12}\n        hasActiveFilters={true}\n        numActiveFilters={2}>\n        Composers\n      </EuiFilterButton>\n    );\n\n    return (\n      <EuiFilterGroup fullWidth={true}>\n        <EuiFilterButton\n          grow={false}\n          hasActiveFilters={this.state.isFilterOn}\n          onClick={this.toggleFilter}>\n          Filter\n        </EuiFilterButton>\n        <EuiFilterButton\n          withNext\n          grow={false}\n          hasActiveFilters={this.state.isOnFilterOn}\n          onClick={this.toggleOnFilter}>\n          On\n        </EuiFilterButton>\n        <EuiFilterButton\n          grow={false}\n          hasActiveFilters={this.state.isOffFilterOn}\n          onClick={this.toggleOffFilter}>\n          Off\n        </EuiFilterButton>\n        <EuiPopover\n          id=\"popover\"\n          ownFocus\n          button={button}\n          isOpen={this.state.isPopoverOpen}\n          closePopover={this.closePopover.bind(this)}\n          panelPaddingSize=\"none\"\n          withTitle>\n          <div className=\"euiFilterSelect__note\">\n            <div className=\"euiFilterSelect__noteContent\">\n              <EuiIcon type=\"minusInCircle\" />\n              <EuiSpacer size=\"xs\" />\n              <p>No filters found</p>\n            </div>\n          </div>\n        </EuiPopover>\n        <EuiFilterButton\n          numFilters={12}\n          hasActiveFilters={this.state.isFilterOn}\n          onClick={this.toggleFilter}>\n          Filter with a very long name\n        </EuiFilterButton>\n      </EuiFilterGroup>\n    );\n  }\n}\n"