module.exports = "import React, { Fragment } from 'react';\n\nimport { EuiFlexGrid, EuiFlexItem } from '../../../../src/components';\n\nimport { isColorDark } from '../../../../src/services';\n\nconst SWATCH_STYLE = {\n  width: 100,\n  height: 100,\n  padding: 16,\n};\n\nconst rgb = (r, g, b) => {\n  return `rgb(${r}, ${g}, ${b})`;\n};\n\nexport default () => {\n  const DARK_COLORS = [\n    [0, 104, 55],\n    [165, 0, 38],\n    [0, 0, 0],\n    [219, 19, 116],\n    [73, 0, 146],\n    [70, 26, 10],\n    [146, 0, 0],\n  ];\n\n  const LIGHT_COLORS = [\n    [191, 161, 128],\n    [249, 133, 16],\n    [0, 179, 164],\n    [212, 157, 170],\n    [255, 255, 255],\n    [254, 182, 219],\n    [230, 194, 32],\n  ];\n\n  return (\n    <Fragment>\n      <EuiFlexGrid>\n        {DARK_COLORS.map(color => (\n          <EuiFlexItem\n            style={{ backgroundColor: rgb(...color), ...SWATCH_STYLE }}\n            key={color.join('')}>\n            {isColorDark(...color) ? (\n              <div style={{ color: 'white' }}>Dark</div>\n            ) : (\n              <div style={{ color: 'black' }}>Light</div>\n            )}\n          </EuiFlexItem>\n        ))}\n      </EuiFlexGrid>\n\n      <EuiFlexGrid>\n        {LIGHT_COLORS.map(color => (\n          <EuiFlexItem\n            style={{ backgroundColor: rgb(...color), ...SWATCH_STYLE }}\n            key={color.join('')}>\n            {isColorDark(...color) ? (\n              <div style={{ color: 'white' }}>Dark</div>\n            ) : (\n              <div style={{ color: 'black' }}>Light</div>\n            )}\n          </EuiFlexItem>\n        ))}\n      </EuiFlexGrid>\n    </Fragment>\n  );\n};\n"