module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiButtonEmpty,\n  EuiContextMenuPanel,\n  EuiContextMenuItem,\n  EuiPopover,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isPopoverOpen: false,\n    };\n  }\n\n  onButtonClick = () => {\n    this.setState(prevState => ({\n      isPopoverOpen: !prevState.isPopoverOpen,\n    }));\n  };\n\n  closePopover = () => {\n    this.setState({\n      isPopoverOpen: false,\n    });\n  };\n\n  render() {\n    const button = (\n      <EuiButtonEmpty\n        size=\"s\"\n        type=\"text\"\n        iconType=\"arrowDown\"\n        iconSide=\"right\"\n        onClick={this.onButtonClick}>\n        Rows per page: 50\n      </EuiButtonEmpty>\n    );\n\n    const items = [\n      <EuiContextMenuItem\n        key=\"10 rows\"\n        icon=\"empty\"\n        onClick={() => {\n          this.closePopover();\n          window.alert('10 rows');\n        }}>\n        10 rows\n      </EuiContextMenuItem>,\n      <EuiContextMenuItem\n        key=\"20 rows\"\n        icon=\"empty\"\n        onClick={() => {\n          this.closePopover();\n          window.alert('20 rows');\n        }}>\n        20 rows\n      </EuiContextMenuItem>,\n      <EuiContextMenuItem\n        key=\"50 rows\"\n        icon=\"check\"\n        onClick={() => {\n          this.closePopover();\n          window.alert('50 rows');\n        }}>\n        50 rows\n      </EuiContextMenuItem>,\n      <EuiContextMenuItem\n        key=\"100 rows\"\n        icon=\"empty\"\n        onClick={() => {\n          this.closePopover();\n          window.alert('100 rows');\n        }}>\n        100 rows\n      </EuiContextMenuItem>,\n    ];\n\n    return (\n      <EuiPopover\n        id=\"singlePanel\"\n        button={button}\n        isOpen={this.state.isPopoverOpen}\n        closePopover={this.closePopover}\n        panelPaddingSize=\"none\"\n        anchorPosition=\"downLeft\">\n        <EuiContextMenuPanel items={items} />\n      </EuiPopover>\n    );\n  }\n}\n"