module.exports = "import React, { Component, Fragment } from 'react';\n\nimport {\n  EuiRange,\n  EuiSpacer,\n  EuiTitle,\n  EuiDualRange,\n} from '../../../../src/components';\n\nimport makeId from '../../../../src/components/form/form_row/make_id';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      value: '20',\n      dualValue: [20, 100],\n    };\n  }\n\n  onChange = e => {\n    this.setState({\n      value: e.target.value,\n    });\n  };\n\n  onDualChange = value => {\n    this.setState({\n      dualValue: value,\n    });\n  };\n\n  render() {\n    return (\n      <Fragment>\n        <EuiRange\n          id={makeId()}\n          step={10}\n          value={this.state.value}\n          onChange={this.onChange}\n          showTicks\n        />\n\n        <EuiSpacer size=\"xl\" />\n\n        <EuiTitle size=\"xxs\">\n          <h3>Custom tick interval</h3>\n        </EuiTitle>\n\n        <EuiSpacer size=\"l\" />\n\n        <EuiRange\n          id={makeId()}\n          value={this.state.value}\n          onChange={this.onChange}\n          showInput\n          showRange\n          showTicks\n          tickInterval={20}\n        />\n\n        <EuiSpacer size=\"xl\" />\n\n        <EuiTitle size=\"xxs\">\n          <h3>Custom ticks object</h3>\n        </EuiTitle>\n\n        <EuiSpacer size=\"l\" />\n\n        <EuiDualRange\n          id={makeId()}\n          value={this.state.dualValue}\n          onChange={this.onDualChange}\n          showTicks\n          ticks={[{ label: '20kb', value: 20 }, { label: '100kb', value: 100 }]}\n          showInput\n        />\n      </Fragment>\n    );\n  }\n}\n"