module.exports = "import React, { useEffect, useState } from 'react';\n\nimport { EuiInnerText } from '../../../../src/components/inner_text';\n\nimport {\n  EuiBadge,\n  EuiCode,\n  EuiFlexGroup,\n  EuiHighlight,\n  EuiFlexItem,\n  EuiHorizontalRule,\n  EuiPanel,\n  EuiText,\n} from '../../../../src/components';\n\nexport default () => {\n  const first = 'First';\n  const second = 'Second';\n  const [thing, setThing] = useState(first);\n  const [[thing2, type], setThingAndType] = useState([first, 'span']);\n  useEffect(() => {\n    setTimeout(() => {\n      const newThing = thing === second ? first : second;\n      const newType = type === 'div' ? 'span' : 'div';\n      setThing(newThing);\n      setThingAndType([newThing, newType]);\n    }, 5000);\n  }, [thing]);\n\n  return (\n    <EuiText size=\"s\">\n      <h5>Example:</h5>\n      <EuiInnerText>\n        {(ref, innerText) => (\n          <React.Fragment>\n            <EuiFlexGroup>\n              <EuiFlexItem grow={false}>\n                <EuiPanel paddingSize=\"s\" grow={false}>\n                  <span ref={ref} title={innerText}>\n                    Simple string content\n                  </span>\n                </EuiPanel>\n              </EuiFlexItem>\n            </EuiFlexGroup>\n            <h5 className=\"eui-displayInlineBlock\">Output:</h5>{' '}\n            <EuiCode>{innerText}</EuiCode>\n          </React.Fragment>\n        )}\n      </EuiInnerText>\n\n      <EuiHorizontalRule margin=\"xl\" />\n\n      <h5>Example with complex children:</h5>\n      <EuiInnerText>\n        {(ref, innerText) => (\n          <React.Fragment>\n            <EuiFlexGroup>\n              <EuiFlexItem grow={false}>\n                <EuiPanel paddingSize=\"s\" grow={false}>\n                  <span ref={ref} title={innerText}>\n                    <EuiHighlight search=\"content\">\n                      EuiHighlight content\n                    </EuiHighlight>{' '}\n                    <EuiBadge>with EuiBadge</EuiBadge>\n                  </span>\n                </EuiPanel>\n              </EuiFlexItem>\n            </EuiFlexGroup>\n            <h5 className=\"eui-displayInlineBlock\">Output:</h5>{' '}\n            <EuiCode>{innerText}</EuiCode>\n          </React.Fragment>\n        )}\n      </EuiInnerText>\n\n      <EuiHorizontalRule margin=\"xl\" />\n\n      <h5>Example with updating content:</h5>\n      <EuiInnerText>\n        {(ref, innerText) => (\n          <React.Fragment>\n            <EuiFlexGroup>\n              <EuiFlexItem grow={false}>\n                <EuiPanel paddingSize=\"s\" grow={false}>\n                  <span ref={ref} title={innerText}>\n                    {thing}\n                  </span>\n                </EuiPanel>\n              </EuiFlexItem>\n            </EuiFlexGroup>\n            <h5 className=\"eui-displayInlineBlock\">Output:</h5>{' '}\n            <EuiCode>{innerText}</EuiCode>\n          </React.Fragment>\n        )}\n      </EuiInnerText>\n\n      <EuiHorizontalRule margin=\"xl\" />\n\n      <h5>Example with updating element:</h5>\n      <EuiInnerText>\n        {(ref, innerText) => (\n          <React.Fragment>\n            <EuiFlexGroup>\n              <EuiFlexItem grow={false}>\n                <EuiPanel paddingSize=\"s\" grow={false}>\n                  {React.createElement(\n                    type,\n                    {\n                      ref,\n                      title: innerText,\n                    },\n                    thing2\n                  )}\n                </EuiPanel>\n              </EuiFlexItem>\n            </EuiFlexGroup>\n            <h5 className=\"eui-displayInlineBlock\">Output:</h5>{' '}\n            <EuiCode>{innerText}</EuiCode>\n          </React.Fragment>\n        )}\n      </EuiInnerText>\n    </EuiText>\n  );\n};\n"