module.exports = "import React, { Component } from 'react';\nimport { formatDate } from '../../../../../src/services/format';\nimport { createDataStore } from '../data_store';\n\nimport {\n  EuiBasicTable,\n  EuiHealth,\n  EuiIcon,\n  EuiLink,\n  EuiToolTip,\n} from '../../../../../src/components';\n\n/*\nExample user object:\n\n{\n  id: '1',\n  firstName: 'john',\n  lastName: 'doe',\n  github: 'johndoe',\n  dateOfBirth: Date.now(),\n  nationality: 'NL',\n  online: true\n}\n\nExample country object:\n\n{\n  code: 'NL',\n  name: 'Netherlands',\n  flag: '🇳🇱'\n}\n*/\n\nconst store = createDataStore();\n\nexport class Table extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      pageIndex: 0,\n      pageSize: 5,\n      sortField: 'firstName',\n      sortDirection: 'asc',\n    };\n  }\n\n  onTableChange = ({ page = {}, sort = {} }) => {\n    const { index: pageIndex, size: pageSize } = page;\n\n    const { field: sortField, direction: sortDirection } = sort;\n\n    this.setState({\n      pageIndex,\n      pageSize,\n      sortField,\n      sortDirection,\n    });\n  };\n\n  render() {\n    const { pageIndex, pageSize, sortField, sortDirection } = this.state;\n\n    const { pageOfItems, totalItemCount } = store.findUsers(\n      pageIndex,\n      pageSize,\n      sortField,\n      sortDirection\n    );\n\n    const columns = [\n      {\n        field: 'firstName',\n        name: 'First Name',\n        sortable: true,\n        truncateText: true,\n        mobileOptions: {\n          render: item => (\n            <span>\n              {item.firstName} {item.lastName}\n            </span>\n          ),\n          header: false,\n          truncateText: false,\n          enlarge: true,\n          fullWidth: true,\n        },\n      },\n      {\n        field: 'lastName',\n        name: 'Last Name',\n        sortable: true,\n        truncateText: true,\n        mobileOptions: {\n          show: false,\n        },\n      },\n      {\n        field: 'github',\n        name: (\n          <EuiToolTip content=\"Their mascot is the Octokitty\">\n            <span>\n              Github{' '}\n              <EuiIcon\n                size=\"s\"\n                color=\"subdued\"\n                type=\"questionInCircle\"\n                className=\"eui-alignTop\"\n              />\n            </span>\n          </EuiToolTip>\n        ),\n        sortable: true,\n        render: username => (\n          <EuiLink href={`https://github.com/${username}`} target=\"_blank\">\n            {username}\n          </EuiLink>\n        ),\n      },\n      {\n        field: 'dateOfBirth',\n        name: (\n          <EuiToolTip content=\"Colloquially known as a 'birthday'\">\n            <span>\n              Date of Birth{' '}\n              <EuiIcon\n                size=\"s\"\n                color=\"subdued\"\n                type=\"questionInCircle\"\n                className=\"eui-alignTop\"\n              />\n            </span>\n          </EuiToolTip>\n        ),\n        dataType: 'date',\n        render: date => formatDate(date, 'dobLong'),\n        sortable: true,\n      },\n      {\n        field: 'nationality',\n        name: (\n          <EuiToolTip content=\"The nation in which this person resides\">\n            <span>\n              Nationality{' '}\n              <EuiIcon\n                size=\"s\"\n                color=\"subdued\"\n                type=\"questionInCircle\"\n                className=\"eui-alignTop\"\n              />\n            </span>\n          </EuiToolTip>\n        ),\n        sortable: true,\n        render: countryCode => {\n          const country = store.getCountry(countryCode);\n          return `${country.flag} ${country.name}`;\n        },\n      },\n      {\n        field: 'online',\n        name: (\n          <EuiToolTip content=\"Free to talk or busy with business\">\n            <span>\n              Online{' '}\n              <EuiIcon\n                size=\"s\"\n                color=\"subdued\"\n                type=\"questionInCircle\"\n                className=\"eui-alignTop\"\n              />\n            </span>\n          </EuiToolTip>\n        ),\n        dataType: 'boolean',\n        sortable: true,\n        render: online => {\n          const color = online ? 'success' : 'danger';\n          const label = online ? 'Online' : 'Offline';\n          return <EuiHealth color={color}>{label}</EuiHealth>;\n        },\n      },\n    ];\n\n    const pagination = {\n      pageIndex: pageIndex,\n      pageSize: pageSize,\n      totalItemCount: totalItemCount,\n      pageSizeOptions: [3, 5, 8],\n    };\n\n    const sorting = {\n      sort: {\n        field: sortField,\n        direction: sortDirection,\n      },\n    };\n\n    return (\n      <div>\n        <EuiBasicTable\n          items={pageOfItems}\n          columns={columns}\n          pagination={pagination}\n          sorting={sorting}\n          onChange={this.onTableChange}\n        />\n      </div>\n    );\n  }\n}\n"