module.exports = "import React, { Component } from 'react';\n\nimport { EuiSwitch, EuiStat, EuiSpacer } from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isLoading: true,\n    };\n  }\n\n  onToggleChange = e => {\n    this.setState({ isLoading: e.target.checked });\n  };\n\n  render() {\n    return (\n      <div>\n        <EuiStat\n          title=\"7,600 mm\"\n          description=\"Total People\"\n          isLoading={this.state.isLoading}\n        />\n        <EuiSpacer />\n        <EuiSwitch\n          label=\"Show as loading\"\n          checked={this.state.isLoading}\n          onChange={this.onToggleChange}\n        />\n      </div>\n    );\n  }\n}\n"